/// `IosLiveUpdateOptions.color`, `backgroundColor` and `foregroundColor`, or
/// system colors while
/// the Always-On display dims the Lock Screen.
struct LiveUpdatesPalette {
  let tint: Color?
  let background: Color?
  /// Lock Screen text (`IosLiveUpdateOptions.foregroundColor`).
  let foreground: Color?

  /// Secondary text: the foreground color at 70%, else the system's.
  var secondaryText: AnyShapeStyle {
    foreground.map { AnyShapeStyle($0.opacity(0.7)) } ?? AnyShapeStyle(.secondary)
  }

  init(_ state: LiveUpdatesAttributes.ContentState, luminanceReduced: Bool) {
    tint = luminanceReduced ? nil : Self.color(state.tintArgb)
    background = luminanceReduced ? nil : Self.color(state.backgroundArgb)
    foreground = luminanceReduced ? nil : Self.color(state.foregroundArgb)
  }

  private init(tint: Color?) {
    self.tint = tint
    background = nil
    foreground = nil
  }

  /// The accent alone, for the Dynamic Island (whose background stays dark).
  var islandOnly: LiveUpdatesPalette { LiveUpdatesPalette(tint: tint) }

  static func color(_ argb: Int?) -> Color? {
    guard let argb, argb >= 0, argb <= 0xFFFF_FFFF else { return nil }
    func channel(_ shift: Int) -> Double { Double((argb >> shift) & 0xFF) / 255 }
    return Color(.sRGB, red: channel(16), green: channel(8), blue: channel(0), opacity: channel(24))
  }
}

/// One small item of the Dynamic Island: "progress", "timer", "title",
/// "body", "icon" or "extra:<key>".
struct LiveUpdatesIslandItem: View {
  let state: LiveUpdatesAttributes.ContentState
  let content: String?

  var body: some View {
    switch content {
    case "progress":
      if let progress = state.progress {
        ProgressView(value: progress).progressViewStyle(.circular)
      }
    case "timer":
      LiveUpdatesTimerText(state: state).frame(maxWidth: 52)
    case "icon":
      LiveUpdatesAppIcon(name: state.iconName)
    case let text?:
      if let value = state.liveUpdatesText(text) {
        LiveUpdatesNarrowText(text: value)
      }
    case nil:
      EmptyView()
    }
  }
}

/// Text that is hidden when the Dynamic Island is limited in width (iOS 27).
struct LiveUpdatesNarrowText: View {
  let text: String

  var body: some View {
    #if compiler(>=6.4)
      if #available(iOS 27.0, *) {
        LiveUpdatesWidthAwareText(text: text)
      } else {
        label
      }
    #else
      label
    #endif
  }

  private var label: some View {
    Text(text).lineLimit(1).frame(maxWidth: 64)
  }
}

#if compiler(>=6.4)
  @available(iOS 27.0, *)
  private struct LiveUpdatesWidthAwareText: View {
    let text: String
    @Environment(\.isDynamicIslandLimitedInWidth) private var limitedInWidth

    var body: some View {
      if !limitedInWidth {
        Text(text).lineLimit(1).frame(maxWidth: 64)
      }
    }
  }
#endif

/// `LiveUpdateContent.timer`, counted by the system: it keeps running without
/// updates. A countdown stops at zero.
struct LiveUpdatesTimerText: View {
  let state: LiveUpdatesAttributes.ContentState

  var body: some View {
    Group {
      if let end = state.liveUpdatesTimerEnd {
        let now = Date()
        Text(timerInterval: min(now, end)...end, countsDown: true)
      } else if let start = state.liveUpdatesTimerStart {
        Text(start, style: .timer)
      }
    }
    .monospacedDigit()
    .multilineTextAlignment(.trailing)
  }
}

/// `LiveUpdateContent.actions`. Background actions run
/// `LiveUpdatesActionIntent`; `opensApp` actions open the app with a URL.
struct LiveUpdatesActionButtons: View {
  let actions: [LiveUpdatesAction]
  let activityID: String

  var body: some View {
    if !actions.isEmpty {
      HStack(spacing: 8) {
        ForEach(actions) { action in
          if action.opensApp, let url = action.liveUpdatesURL(activityID: activityID) {
            Link(destination: url) { LiveUpdatesActionLabel(action: action) }
          } else if action.requiresUnlock {
            Button(
              intent: LiveUpdatesSecureActionIntent(activityId: activityID, actionId: action.id)
            ) {
              LiveUpdatesActionLabel(action: action)
            }
          } else {
            Button(intent: LiveUpdatesActionIntent(activityId: activityID, actionId: action.id)) {
              LiveUpdatesActionLabel(action: action)
            }
          }
        }
      }
      .buttonStyle(.bordered)
    }
  }
}

struct LiveUpdatesActionLabel: View {
  let action: LiveUpdatesAction

  var body: some View {
    if let symbol = action.systemImage {
      Label(action.title, systemImage: symbol).frame(maxWidth: .infinity)
    } else {
      Text(action.title).frame(maxWidth: .infinity)
    }
  }
}

/// The image passed as `LiveUpdateContent.image`, else the icon.
struct LiveUpdatesThumbnail: View {
  let state: LiveUpdatesAttributes.ContentState

  var body: some View {
    if let url = LiveUpdatesImages.url(state.image),
      let image = UIImage(contentsOfFile: url.path)
    {
      Image(uiImage: image)
        .resizable()
        .scaledToFill()
        .clipShape(RoundedRectangle(cornerRadius: 8))
    } else {
      LiveUpdatesAppIcon(name: state.iconName)
    }
  }
}

/// `LiveUpdateContent.iconName` from this extension's asset catalog.
struct LiveUpdatesAppIcon: View {
  let name: String?

  var body: some View {
    if let name {
      Image(name).resizable().scaledToFit()
    } else {
      Image(systemName: "bolt.circle.fill").resizable().scaledToFit()
    }
  }
}

extension LiveUpdatesAttributes.ContentState {
  /// Delivered to `LiveUpdates.onTap` in Dart.
  var liveUpdatesTapURL: URL? {
    guard let route else { return nil }
    return liveUpdatesAppURL(host: "tap", [URLQueryItem(name: "route", value: route)])
  }

  // Values from a push are checked: about 3,000 years either way of 1970.
  var liveUpdatesTimerEnd: Date? { Self.liveUpdatesDate(timerEnd) }
  var liveUpdatesTimerStart: Date? { Self.liveUpdatesDate(timerStart) }
  var liveUpdatesHasTimer: Bool { liveUpdatesTimerEnd != nil || liveUpdatesTimerStart != nil }

  /// `IosLiveUpdateOptions.color` for the Dynamic Island keyline.
  var liveUpdatesKeylineTint: Color? { LiveUpdatesPalette.color(tintArgb) }

  /// `layout` when its data is present ("timer" needs a timer, "metrics"
  /// metrics, "stepper" steps, "journey" a journey), else "standard". Other
  /// names are returned as they are, for layouts added to the layout file.
  var liveUpdatesLayout: String {
    switch layout {
    case "timer": return liveUpdatesHasTimer ? "timer" : "standard"
    case "metrics": return metrics.isEmpty ? "standard" : "metrics"
    case "stepper": return (steps?.labels.isEmpty ?? true) ? "standard" : "stepper"
    case "journey": return journey == nil ? "standard" : "journey"
    case let other?: return other
    case nil: return "standard"
    }
  }

  /// Text for "title", "body" or "extra:<key>".
  func liveUpdatesText(_ content: String) -> String? {
    switch content {
    case "title": return title
    case "body": return body
    default:
      guard content.hasPrefix("extra:") else { return nil }
      return extra[String(content.dropFirst("extra:".count))]
    }
  }

  /// `preferred` if it has something to show, else the first fallback that does.
  func liveUpdatesPick(_ preferred: String?, fallback: [String]) -> String? {
    ([preferred].compactMap { $0 } + fallback).first { liveUpdatesHas($0) }
  }

  private func liveUpdatesHas(_ content: String) -> Bool {
    switch content {
    case "progress": return progress != nil
    case "timer": return liveUpdatesHasTimer
    case "icon": return true
    default: return liveUpdatesText(content) != nil
    }
  }

  private static func liveUpdatesDate(_ seconds: Double?) -> Date? {
    guard let seconds, seconds.isFinite, abs(seconds) < 1e11 else { return nil }
    return Date(timeIntervalSince1970: seconds)
  }
}

extension LiveUpdatesAction {
  /// Opens the app and delivers the press to `LiveUpdates.onAction`.
  func liveUpdatesURL(activityID: String) -> URL? {
    liveUpdatesAppURL(
      host: "action",
      [URLQueryItem(name: "activity", value: activityID), URLQueryItem(name: "action", value: id)])
  }
}

/// Must match LiveUpdatesBridge.tapScheme in the plugin:
/// "liveupdates-<app bundle id>", registered in Runner's Info.plist.
private func liveUpdatesAppURL(host: String, _ items: [URLQueryItem]) -> URL? {
  let appBundleId = (Bundle.main.bundleIdentifier ?? "")
    .split(separator: ".").dropLast().joined(separator: ".")
  var components = URLComponents()
  components.scheme = "liveupdates-\(appBundleId)"
  components.host = host
  components.queryItems = items
  return components.url
}
